Here is a debounce function in JavaScript:

```javascript
function debounce(func, delay) {
  let timeoutId;
  return function(...args) {
    const context = this;
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => {
      func.apply(context, args);
    }, delay);
  };
}

// Example usage:
function handleInput(value) {
  console.log("API call triggered with:", value);
}

const debouncedHandleInput = debounce(handleInput, 500);

// Simulate rapid input events
// debouncedHandleInput("a");
// debouncedHandleInput("ab");
// debouncedHandleInput("abc"); // Only handleInput will be called after 500ms of silence
```

```c
#include <string.h>

void reverseString(char *str) {
    if (str == NULL) {
        return;
    }

    int length = strlen(str);
    int start = 0;
    int end = length - 1;
    char temp;

    while (start < end) {
        // Swap characters
        temp = str[start];
        str[start] = str[end];
        str[end] = temp;

        // Move pointers
        start++;
        end--;
    }
}
```

