def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True
```

Here is a JavaScript function that capitalizes the first letter of each word in a sentence.

```javascript
function capitalizeWords(sentence) {
  if (!sentence) {
    return "";
  }
  return sentence.toLowerCase().split(' ')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

// Example usage:
const sentence1 = "hello world, this is a test";
console.log(capitalizeWords(sentence1)); // Output: Hello World, This Is A Test

const sentence2 = "a short sentence";
console.log(capitalizeWords(sentence2)); // Output: A Short Sentence
```

Here is a Java method that counts the vowels in a string.

```java
public class StringUtils {
    public static int countVowels(String text) {
        if (text == null) {
            return 0;
        }

        int vowelCount = 0;
        String lowerCaseText = text.toLowerCase();
        String vowels = "aeiou";

        for (int i = 0; i < lowerCaseText.length(); i++) {
            char ch = lowerCaseText.charAt(i);
            if (vowels.indexOf(ch) != -1) {
                vowelCount++;
            }
        }
        return vowelCount;
    }

    public static void main(String[] args) {
        String sample = "Hello World";
        int count = countVowels(sample);
        System.out.println("The number of vowels in \"" + sample + "\" is: " + count); // Output: 3
    }
}
```
